#include <cstdio>
#include <algorithm>
#include <iostream>

#define LL long long

#define FOR(i, x, y) for (int i = x; i <= y; i++)
#define FOR_REVERSE(i, x, y) for (int i = x; i >= y; i--)

const int MAXP = 1e6 + 1e5, MOD = 1e9 + 7;

LL k, p;
int tot;
LL ans;
int vis[MAXP];
int val[MAXP];

void modify(LL &x) { x = (x % MOD + MOD) % MOD; }

void breadth_first_search(int x)
{
    ++tot;
    int start = x;
    LL weight = 1;
    do {
        vis[x] = true;
        x = x * k % p;
        weight = weight * k % p;
    } while (x != start);
    modify(ans *= (weight == 1 ? p : 1));
}

void process()
{
    if (k == 0) {
        LL product = 1;
        FOR(i, 1, p - 1)
            product = product * p % MOD;
        printf("%lld\n", product);
        return;
    }
    ans = 1;
    FOR(i, 0, p - 1)
        if (vis[i] == 0)
            breadth_first_search(i);
    printf("%lld\n", ans);
}

int main()
{
    if (fopen("B.in", "r") != NULL) {
        freopen("B.in", "r", stdin);
        freopen("B.out", "w", stdout);
    }

    scanf("%lld%lld", &p, &k);
    process();

    return 0;
}
